use anyhow :: { Context , Result } ; use lazy_static :: lazy_static ; use rayon :: prelude :: * ; use regex :: Regex ; use std :: fs ; use std :: path :: { Path , PathBuf } ; use toml_edit :: DocumentMut ; use super :: * ; # [doc = " Find all workspace member Cargo.toml files"] # [doc = ""] # [doc = " Returns the root Cargo.toml and any explicitly defined workspace member Cargo.toml files."] pub fn find_workspace_members (workspace_path : & Path) -> Result < Vec < PathBuf > > { let mut members = Vec :: new () ; let cargo_toml_path = workspace_path . join ("Cargo.toml") ; if cargo_toml_path . exists () { members . push (cargo_toml_path . clone ()) ; let content = fs :: read_to_string (& cargo_toml_path) . with_context (| | format ! ("Failed to read Cargo.toml at {:?}" , cargo_toml_path)) ? ; if let Ok (doc) = content . parse :: < toml_edit :: DocumentMut > () { if let Some (workspace) = doc . get ("workspace") { if let Some (members_list) = workspace . get ("members") { if let Some (array) = members_list . as_array () { for pattern in array . iter () . filter_map (| p | p . as_str ()) { let search_pattern = workspace_path . join (pattern) . join ("Cargo.toml") ; if let Ok (paths) = glob :: glob (& search_pattern . to_string_lossy ()) { for path in paths . filter_map (| p | p . ok ()) { if ! members . contains (& path) { members . push (path) ; } } } } } } } } } Ok (members) }